CREATE TABLE applied_op (op_id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, entity TEXT NOT NULL, row_id TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('applied','applied_partial','duplicate','rejected')), assigned_rev INTEGER, applied_at TEXT NOT NULL) STRICT;
CREATE TABLE consent_event (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, type TEXT NOT NULL CHECK (type IN ('health','ai_coach')), action TEXT NOT NULL CHECK (action IN ('grant','withdraw')), text_version TEXT NOT NULL) STRICT;
CREATE TABLE gym (id TEXT PRIMARY KEY, name TEXT NOT NULL CHECK (length(name) BETWEEN 2 AND 60), name_key TEXT NOT NULL, city TEXT NOT NULL CHECK (length(city) BETWEEN 2 AND 60), city_key TEXT NOT NULL, load_settings TEXT NOT NULL CHECK (json_valid(load_settings)), created_by TEXT REFERENCES user(id) ON DELETE SET NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, UNIQUE (name_key, city_key)) STRICT;
CREATE TABLE gym_equipment (id TEXT PRIMARY KEY, gym_id TEXT NOT NULL REFERENCES gym(id) ON DELETE CASCADE, equipment_code TEXT NOT NULL, added_by TEXT REFERENCES user(id) ON DELETE SET NULL, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, CHECK (id = gym_id || ':' || equipment_code)) STRICT;
CREATE TABLE gym_history (id TEXT PRIMARY KEY, gym_id TEXT NOT NULL REFERENCES gym(id) ON DELETE CASCADE, author_id TEXT REFERENCES user(id) ON DELETE SET NULL, at TEXT NOT NULL, action TEXT NOT NULL CHECK (action IN ('create','update_info','add_equipment','remove_equipment','update_load_settings')), detail TEXT NOT NULL CHECK (json_valid(detail))) STRICT;
CREATE TABLE health_screening (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, caution INTEGER CHECK (caution IN (0,1)), questionnaire_version TEXT, answered_at TEXT, CHECK (id = owner_id), CHECK (deleted_at IS NOT NULL OR (caution IS NOT NULL AND questionnaire_version IS NOT NULL AND answered_at IS NOT NULL))) STRICT;
CREATE TABLE home_equipment (id TEXT PRIMARY KEY, place_id TEXT NOT NULL REFERENCES place(id) ON DELETE CASCADE, equipment_code TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, CHECK (id = place_id || ':' || equipment_code)) STRICT;
CREATE TABLE invitation (id TEXT PRIMARY KEY, code_hash TEXT NOT NULL UNIQUE, note TEXT CHECK (length(note) <= 60), birth_date TEXT, is_admin_bootstrap INTEGER NOT NULL DEFAULT 0 CHECK (is_admin_bootstrap IN (0,1)), created_by TEXT REFERENCES user(id) ON DELETE SET NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, used_at TEXT, used_by TEXT REFERENCES user(id) ON DELETE SET NULL, revoked_at TEXT) STRICT;
CREATE TABLE limitation (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, body_area TEXT CHECK (body_area IN ('shoulder','elbow','wrist_hand','neck','upper_back','lower_back','hip','knee','ankle_foot','other')), side TEXT CHECK (side IN ('left','right','both','not_applicable')), severity TEXT CHECK (severity IN ('mild','severe')), note TEXT CHECK (length(note) <= 200), active INTEGER CHECK (active IN (0,1)), CHECK (deleted_at IS NOT NULL OR (body_area IS NOT NULL AND side IS NOT NULL AND severity IS NOT NULL AND active IS NOT NULL))) STRICT;
CREATE TABLE password_reset (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, code_hash TEXT NOT NULL UNIQUE, created_by TEXT REFERENCES user(id) ON DELETE SET NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, used_at TEXT, cancelled_at TEXT) STRICT;
CREATE TABLE place (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, kind TEXT NOT NULL CHECK (kind IN ('gym','home')), gym_id TEXT REFERENCES gym(id), name TEXT CHECK (length(name) <= 30), is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0,1)), visible_at_gym INTEGER NOT NULL DEFAULT 0 CHECK (visible_at_gym IN (0,1)), load_settings TEXT CHECK (json_valid(load_settings)), CHECK (kind = 'home' OR load_settings IS NULL), CHECK ((kind = 'gym') = (gym_id IS NOT NULL)), CHECK (kind = 'home' OR name IS NULL)) STRICT;
CREATE TABLE schema_migrations (id TEXT PRIMARY KEY, breaking INTEGER NOT NULL CHECK (breaking IN (0,1)), applied_at TEXT NOT NULL) STRICT;
CREATE TABLE security_event (id TEXT PRIMARY KEY, at TEXT NOT NULL, type TEXT NOT NULL, actor_id TEXT, target_id TEXT, tailnet_ip TEXT, outcome TEXT NOT NULL CHECK (outcome IN ('success','failure','blocked')), details TEXT CHECK (json_valid(details))) STRICT;
CREATE TABLE server_meta (id INTEGER PRIMARY KEY CHECK (id = 1), server_epoch TEXT NOT NULL, epoch_started_at TEXT NOT NULL, epoch_base_rev INTEGER NOT NULL DEFAULT 0, sync_counter INTEGER NOT NULL DEFAULT 0, tombstone_purge_rev INTEGER NOT NULL DEFAULT 0, catalog_version TEXT, catalog_updated_at TEXT) STRICT;
CREATE TABLE session (id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, user_id TEXT REFERENCES user(id) ON DELETE SET NULL, created_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, expires_at TEXT NOT NULL, must_change_password INTEGER NOT NULL DEFAULT 0 CHECK (must_change_password IN (0,1)), revoked_at TEXT, revoked_reason TEXT CHECK (revoked_reason IN ('logout','logout_all','password_change','password_reset','admin','account_deleted'))) STRICT;
CREATE TABLE sync_rejection (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, op_id TEXT NOT NULL, entity TEXT NOT NULL, row_id TEXT NOT NULL, code TEXT NOT NULL CHECK (code IN ('validation','forbidden','parent_rejected','stale_revision','unknown_entity','protocol')), detail_json TEXT CHECK (json_valid(detail_json)), dismissed_at TEXT) STRICT;
CREATE TABLE training_profile (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL, deleted_at TEXT, goal TEXT CHECK (goal IN ('muscle','strength','fat_loss','fitness','sport_support')), experience TEXT CHECK (experience IN ('none','lt_6_months','6_to_24_months','gt_24_months')), days_per_week INTEGER CHECK (days_per_week BETWEEN 2 AND 4), session_minutes INTEGER CHECK (session_minutes IN (30,45,60,75,90)), sport_code TEXT, sport_other_label TEXT CHECK (length(sport_other_label) <= 40), cautious_mode INTEGER NOT NULL DEFAULT 0 CHECK (cautious_mode IN (0,1)), CHECK (id = owner_id)) STRICT;
CREATE TABLE user (id TEXT PRIMARY KEY, username TEXT NOT NULL, username_key TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('admin','member')), status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','disabled')), birth_date TEXT NOT NULL, terms_version TEXT, terms_accepted_at TEXT, last_login_at TEXT, password_changed_at TEXT, onboarding_step TEXT CHECK (onboarding_step IN ('goal','sport','place_kind','place','experience','availability','health','ready')), onboarding_completed_at TEXT, invitation_id TEXT REFERENCES invitation(id) ON DELETE SET NULL, rev INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT REFERENCES user(id) ON DELETE SET NULL) STRICT;
CREATE INDEX applied_op_user_applied_idx ON applied_op (user_id, applied_at);
CREATE INDEX consent_event_owner_rev_idx ON consent_event (owner_id, rev);
CREATE INDEX consent_event_owner_type_created_idx ON consent_event (owner_id, type, created_at);
CREATE INDEX consent_event_rev_idx ON consent_event (rev);
CREATE INDEX gym_equipment_gym_idx ON gym_equipment (gym_id);
CREATE INDEX gym_equipment_rev_idx ON gym_equipment (rev);
CREATE INDEX gym_history_gym_at_idx ON gym_history (gym_id, at);
CREATE INDEX gym_rev_idx ON gym (rev);
CREATE INDEX health_screening_owner_rev_idx ON health_screening (owner_id, rev);
CREATE INDEX health_screening_rev_idx ON health_screening (rev);
CREATE INDEX home_equipment_owner_rev_idx ON home_equipment (owner_id, rev);
CREATE INDEX home_equipment_place_idx ON home_equipment (place_id);
CREATE INDEX home_equipment_rev_idx ON home_equipment (rev);
CREATE INDEX limitation_owner_rev_idx ON limitation (owner_id, rev);
CREATE INDEX limitation_rev_idx ON limitation (rev);
CREATE INDEX password_reset_user_idx ON password_reset (user_id);
CREATE INDEX place_gym_idx ON place (gym_id);
CREATE UNIQUE INDEX place_owner_gym_uq ON place (owner_id, gym_id) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX place_owner_primary_uq ON place (owner_id) WHERE is_primary = 1 AND deleted_at IS NULL;
CREATE INDEX place_owner_rev_idx ON place (owner_id, rev);
CREATE INDEX place_rev_idx ON place (rev);
CREATE INDEX security_event_at_idx ON security_event (at);
CREATE INDEX session_user_idx ON session (user_id);
CREATE INDEX sync_rejection_owner_rev_idx ON sync_rejection (owner_id, rev);
CREATE INDEX sync_rejection_rev_idx ON sync_rejection (rev);
CREATE INDEX training_profile_owner_rev_idx ON training_profile (owner_id, rev);
CREATE INDEX training_profile_rev_idx ON training_profile (rev);
CREATE INDEX user_rev_idx ON user (rev);
